package tchannel

import (
	"fmt"
	"io/ioutil"
	"testing"
)

func BenchmarkCallReqFrame(b *testing.B) {
	cr := reqHasAll.req(b)
	f := cr.Frame

	var service, caller, method []byte

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		cr, err := newLazyCallReq(f)
		if err != nil {
			b.Fatal("Unexpected error")
		}

		// Multiple calls due to peer selection, stats, etc.
		for i := 0; i < 3; i++ {
			service = cr.Service()
			caller = cr.Caller()
			method = cr.Method()
		}
	}
	b.StopTimer()

	fmt.Fprint(ioutil.Discard, service, caller, method)
}

